const REVERSE=Object.fromEntries(Object.entries(MESSAGES).map(([a,b])=>[b,a]));
const REV_RX=new RegExp('(?<![A-Za-z])(?:'+Object.keys(REVERSE).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![A-Za-z])','g');
function locale(){if(window.SensometrixLanguage?.current)return window.SensometrixLanguage.current;try{return localStorage.getItem('sensometrix.language')==='en'?'en':'id';}catch{return 'id';}}
function T(value){const text=String(value??'');return locale()==='en'?text.replace(RX,m=>MESSAGES[m]):text;}
function H(parts,...values){return parts.reduce((s,p,i)=>s+T(p)+(i<values.length?values[i]:''),'');}
function uiText(text){const original=String(text??'').replace(REV_RX,m=>REVERSE[m]);return T(original);}
function uiTitle(text){for(const prefix of ['Audit desain','Design audit','Tetapkan peserta','Assign participant','Riwayat','History'])if(text.startsWith(prefix))return uiText(prefix)+text.slice(prefix.length);return uiText(text);}

